const raw = $json.message?.content || $json.choices?.[0]?.message?.content || '';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  // Attempt extraction if model wrapped JSON in markdown
  const match = raw.match(/```json([\s\S]*?)```/);
  parsed = JSON.parse(match ? match[1] : raw);
}
return [{ json: { script: parsed.script, keywords: parsed.keywords } }];

const hits = $json.hits;
if (!hits || hits.length === 0) throw new Error('No video found for keywords');
// Pick highest-resolution medium variant
const video = hits[0];
const medium = video.videos?.medium?.url || video.videos?.large?.url;
return [{ json: { videoUrl: medium, script: $('Parse AI Output').first().json.script } }];

const output = $json.stdout || '';
const match = output.match(/OUTPUT_PATH=(.+)/);
if (!match) throw new Error('Render did not return OUTPUT_PATH. stdout: ' + output);
return [{ json: { outputPath: match[1].trim(), stdout: output } }];
